use super::*;

/// Build a URN, or `None` when any part is missing or the graph is unknown.
pub fn format_node_urn(graph: NodeGraph, kit: &str, id: &str) -> Option<String> {
    if kit.is_empty() || id.is_empty() {
        return None;
    }
    Some(format!("{}:{}/{}", graph.as_str(), kit, id))
}
